-- State transitions declared for Company: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION organization.companies_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('active', 'dissolved'), ('active', 'inactive'), ('active', 'suspended'), ('inactive', 'active'), ('inactive', 'dissolved'), ('suspended', 'active'), ('suspended', 'dissolved'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: companies.status % -> %', OLD."status", NEW."status"
            USING ERRCODE = 'check_violation', COLUMN = 'status', CONSTRAINT = 'tg_companies__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS companies_status_transition_check ON organization.companies;
CREATE TRIGGER companies_status_transition_check
    BEFORE UPDATE OF "status" ON organization.companies
    FOR EACH ROW EXECUTE FUNCTION organization.companies_status_transition_check();
